@MappingRole: true
define role ZETR_A_EXP_HEAD {
  grant
    select
  on ZETR_DDL_I_EXP_HEAD
    where ( Bukrs ) = aspect pfcg_auth(F_BKPF_BUK, BUKRS, actvt = '03');

  grant
    select
  on ZETR_DDL_C_EXP_HEADER
    where inheriting conditions from entity ZETR_DDL_I_EXP_HEAD;

  // Child interface views: company code is read from the parent export file via _ExportFile
  grant
    select
  on ZETR_DDL_I_EXPORT_INVH
    where ( _ExportFile.Bukrs ) = aspect pfcg_auth( F_BKPF_BUK, BUKRS, ACTVT = '03' );

  grant
    select
  on ZETR_DDL_I_EXPORT_INVI
    where ( _ExportFile.Bukrs ) = aspect pfcg_auth( F_BKPF_BUK, BUKRS, ACTVT = '03' );

  grant
    select
  on ZETR_DDL_I_EXP_TXT
    where ( _ExportFile.Bukrs ) = aspect pfcg_auth( F_BKPF_BUK, BUKRS, ACTVT = '03' );

  grant
    select
  on ZETR_DDL_I_BIL_DOC
    where ( _ExportFile.Bukrs ) = aspect pfcg_auth( F_BKPF_BUK, BUKRS, ACTVT = '03' );

  grant
    select
  on ZETR_DDL_I_COSTING
    where ( _ExportFile.Bukrs ) = aspect pfcg_auth( F_BKPF_BUK, BUKRS, ACTVT = '03' );

  // Child projection views: inherit the condition of the underlying interface view (FROM SUPER needs REDEFINITION)
  grant
    select
  on ZETR_DDL_C_EXP_INVH
    where inheriting conditions from entity ZETR_DDL_I_EXPORT_INVH;

  grant
    select
  on ZETR_DDL_C_EXP_INVI
    where inheriting conditions from entity ZETR_DDL_I_EXPORT_INVI;

  grant
    select
  on ZETR_DDL_C_EXP_TXT
    where inheriting conditions from entity ZETR_DDL_I_EXP_TXT;

  grant
    select
  on ZETR_DDL_C_BIL_DOC
    where inheriting conditions from entity ZETR_DDL_I_BIL_DOC;

  grant
    select
  on ZETR_DDL_C_COSTING_RPR
    where inheriting conditions from entity ZETR_DDL_I_COSTING;

  // Collocutor child (association to parent is named _Header, not _ExportFile)
  grant
    select
  on ZETR_DDL_I_EXP_COLLOCUTOR
    where ( _Header.Bukrs ) = aspect pfcg_auth( F_BKPF_BUK, BUKRS, ACTVT = '03' );

  grant
    select
  on ZETR_DDL_C_EXP_COLLOCUTOR
    where inheriting conditions from entity ZETR_DDL_I_EXP_COLLOCUTOR;
}
